program = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frames = []

    colors = {v for row in grid for v in row if v != 0}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if (all(grid[r0][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r1][c] == color for c in range(c0, c1 + 1)) and
            all(grid[r][c0] == color for r in range(r0, r1 + 1)) and
            all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            frames.append((color, r0, r1, c0, c1))

    sources = []
    for f in frames:
        color, r0, r1, c0, c1 = f
        pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
        if any(any(row) for row in pattern):
            sources.append((f, pattern))

    if not sources:
        return out
    (source, pattern) = sources[0]
    _, sr0, sr1, sc0, sc1 = source
    shape = (sr1 - sr0 + 1, sc1 - sc0 + 1)

    for color, r0, r1, c0, c1 in frames:
        if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
            continue
        if (r1 - r0 + 1, c1 - c0 + 1) != shape:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if out[r][c] == color:
                        out[r][c] = 0
        else:
            for i, r in enumerate(range(r0 + 1, r1)):
                for j, c in enumerate(range(c0 + 1, c1)):
                    out[r][c] = color if pattern[i][j] else 0
    return out
'''
