def get_grid(text, label):
    m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n', text)
    if not m: raise ValueError(label)
    h,w=map(int,m.groups()); start=m.end(); rows=[]
    for line in text[start:].splitlines()[:h]:
        row=list(map(int,line.split()))
        assert len(row)==w,(label,len(row),w,line)
        rows.append(row)
    assert len(rows)==h
    return rows
